style:
:root {
  --doc-ground: #FBFCFD;
  --doc-surface: #F0F4F6;
  --doc-surface-2: #E5EBEF;
  --doc-ink: #0F1518;
  --doc-ink-2: #33444E;
  --doc-ink-mute: #5D6E78;
  --doc-line: #D3DDE3;
  --doc-line-soft: #E4ECF0;
  --doc-accent: #0B6E77;
  --doc-accent-ink: #08545C;
  --doc-accent-wash: #DDEEF0;
  --doc-warn: #8E5406;
  --doc-warn-wash: #F6EBDA;
  --doc-crit: #9C3626;
  --doc-crit-wash: #F7E5E1;

  --doc-f-sans: ui-sans-serif, system-ui, -apple-system, "Segoe UI", "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", sans-serif;
  --doc-f-mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace;

  --doc-measure: 40em;
  --doc-rail: 208px;
}


* { box-sizing: border-box; }


.wrap {
  display: grid; grid-template-columns: var(--doc-rail) minmax(0, 1fr);
  gap: 56px; max-width: 1080px; margin: 0 auto; padding: 0 32px 120px;
}

.rail-inner {
  position: sticky; top: 0; padding: 40px 0;
  display: flex; flex-direction: column; gap: 20px;
  max-height: 100vh; overflow-y: auto;
}
.rail-mark {
  font-family: var(--doc-f-mono); font-size: 11px; letter-spacing: .14em;
  text-transform: uppercase; color: var(--doc-accent);
  border-left: 2px solid var(--doc-accent); padding-left: 10px; line-height: 1.5;
}
.rail nav { display: flex; flex-direction: column; gap: 1px; }
.rail nav a {
  font-size: 13.5px; color: var(--doc-ink-mute); text-decoration: none;
  padding: 3px 0 3px 11px; border-left: 2px solid var(--doc-line-soft);
  transition: color .15s, border-color .15s;
}
.rail nav a:hover, .rail nav a:focus-visible { color: var(--doc-accent); border-left-color: var(--doc-accent); }

main { min-width: 0; padding-top: 40px; }

header.top { padding: 40px 0 32px; border-bottom: 1px solid var(--doc-line); }
.eyebrow {
  font-family: var(--doc-f-mono); font-size: 11.5px; letter-spacing: .16em;
  text-transform: uppercase; color: var(--doc-ink-mute); margin: 0 0 16px;
}
h1 {
  font-size: clamp(31px, 5vw, 44px); line-height: 1.14; letter-spacing: -.024em;
  font-weight: 660; margin: 0 0 18px; text-wrap: balance;
}
.standfirst { font-size: 18px; line-height: 1.68; color: var(--doc-ink-2); max-width: var(--doc-measure); margin: 0; }

h2 { font-size: 25px; letter-spacing: -.017em; font-weight: 640; line-height: 1.25; margin: 0; text-wrap: balance; }
h3 { font-size: 18px; letter-spacing: -.008em; font-weight: 640; margin: 0 0 10px; text-wrap: balance; }

section { padding-top: 54px; }
.sec-head {
  display: flex; align-items: baseline; gap: 14px;
  margin-bottom: 22px; padding-bottom: 12px; border-bottom: 1px solid var(--doc-line);
}
.sec-num { font-family: var(--doc-f-mono); font-size: 12px; color: var(--doc-accent); letter-spacing: .08em; flex: none; }

p { max-width: var(--doc-measure); margin: 0 0 16px; }
ul, ol { max-width: var(--doc-measure); margin: 0 0 16px; padding-left: 22px; }
li { margin-bottom: 9px; }
li::marker { color: var(--doc-ink-mute); }
strong { font-weight: 640; color: var(--doc-ink); }
em { font-style: normal; color: var(--doc-accent-ink); }
a { color: var(--doc-accent); }

code { font-family: var(--doc-f-mono); font-size: .86em; background: var(--doc-surface); border: 1px solid var(--doc-line-soft); border-radius: 3px; padding: .08em .34em; }

/* pattern block */
.pat { border: 1px solid var(--doc-line); margin: 0 0 22px; }
.pat > h3 { margin: 0; padding: 14px 20px 12px; border-bottom: 1px solid var(--doc-line-soft); background: var(--doc-surface); }
.pat .row { display: grid; grid-template-columns: 74px minmax(0,1fr); gap: 0; border-bottom: 1px solid var(--doc-line-soft); }
.pat .row:last-child { border-bottom: none; }
.pat .lbl {
  font-family: var(--doc-f-mono); font-size: 10.5px; letter-spacing: .09em; text-transform: uppercase;
  color: var(--doc-ink-mute); padding: 15px 0 15px 20px; font-weight: 600; line-height: 1.9;
}
.pat .row.why .lbl { color: var(--doc-accent); }
.pat .bd { padding: 13px 20px 13px 4px; }
.pat .bd p { margin: 0 0 10px; max-width: 34em; }
.pat .bd p:last-child { margin-bottom: 0; }
.pat .bd ul { margin: 0; max-width: 34em; }

.analogy {
  border-left: 3px solid var(--doc-accent); background: var(--doc-accent-wash);
  padding: 13px 18px; margin: 0 0 18px; max-width: var(--doc-measure);
  font-size: 15.5px;
}
.analogy p { margin: 0; max-width: none; }
.analogy b { font-family: var(--doc-f-mono); font-size: 10.5px; letter-spacing: .09em; text-transform: uppercase; color: var(--doc-accent-ink); display: block; margin-bottom: 5px; font-weight: 600; }

.stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(124px, 1fr)); gap: 1px; background: var(--doc-line); border: 1px solid var(--doc-line); margin: 26px 0 10px; }
.stat { background: var(--doc-ground); padding: 14px 16px; }
.stat b { display: block; font-size: 25px; font-weight: 640; letter-spacing: -.02em; font-variant-numeric: tabular-nums; line-height: 1.15; }
.stat span { display: block; font-family: var(--doc-f-mono); font-size: 10.5px; letter-spacing: .07em; text-transform: uppercase; color: var(--doc-ink-mute); margin-top: 5px; }

.tw { overflow-x: auto; margin: 0 0 20px; border: 1px solid var(--doc-line); }
table { border-collapse: collapse; width: 100%; font-size: 14.5px; min-width: 420px; }
th, td { text-align: left; padding: 10px 14px; border-bottom: 1px solid var(--doc-line-soft); vertical-align: top; }
th { font-family: var(--doc-f-mono); font-size: 11px; letter-spacing: .07em; text-transform: uppercase; color: var(--doc-ink-mute); font-weight: 600; background: var(--doc-surface); border-bottom: 1px solid var(--doc-line); }
tr:last-child td { border-bottom: none; }
td.num { font-family: var(--doc-f-mono); font-variant-numeric: tabular-nums; white-space: nowrap; }

.note { border: 1px solid var(--doc-line); border-left: 3px solid var(--doc-accent); background: var(--doc-surface); padding: 16px 20px; margin: 0 0 20px; max-width: var(--doc-measure); }
.note.warn { border-left-color: var(--doc-warn); background: var(--doc-warn-wash); }
.note.crit { border-left-color: var(--doc-crit); background: var(--doc-crit-wash); }
.note p:last-child { margin-bottom: 0; }
.note h4 { font-size: 15.5px; font-weight: 640; margin: 0 0 8px; }

.tier { margin-bottom: 32px; }
.tier-label { display: flex; align-items: baseline; gap: 11px; margin-bottom: 13px; flex-wrap: wrap; }
.tier-tag { font-family: var(--doc-f-mono); font-size: 11px; letter-spacing: .08em; text-transform: uppercase; padding: 3px 9px; font-weight: 600; }
.t-a { background: var(--doc-accent); color: var(--doc-ground); }
.t-b { background: var(--doc-warn-wash); color: var(--doc-warn); border: 1px solid var(--doc-warn); }
.t-c { background: var(--doc-crit-wash); color: var(--doc-crit); border: 1px solid var(--doc-crit); }
.tier-label span.d { font-size: 14px; color: var(--doc-ink-mute); }

.steal { border: 1px solid var(--doc-line); }
.steal > div { padding: 14px 18px; border-bottom: 1px solid var(--doc-line-soft); }
.steal > div:last-child { border-bottom: none; }
.steal b { display: block; margin-bottom: 4px; font-weight: 640; }
.steal p { margin: 0; font-size: 14.5px; color: var(--doc-ink-2); max-width: none; line-height: 1.7; }

/* diagrams */
figure { margin: 0 0 26px; }
.fig-wrap { border: 1px solid var(--doc-line); background: var(--doc-surface); padding: 20px 16px 14px; overflow-x: auto; }
figure svg { display: block; width: 100%; height: auto; min-width: 700px; color: var(--doc-ink-2); }
figcaption { font-size: 13.5px; color: var(--doc-ink-mute); margin-top: 11px; max-width: var(--doc-measure); line-height: 1.68; }
.d-box { fill: var(--doc-ground); stroke: currentColor; stroke-width: 1.1; }
.d-box-a { fill: var(--doc-accent-wash); stroke: var(--doc-accent); stroke-width: 1.5; }
.d-t { fill: var(--doc-ink); font-family: var(--doc-f-sans); font-size: 13px; }
.d-t-a { fill: var(--doc-accent-ink); font-family: var(--doc-f-sans); font-size: 13px; font-weight: 640; }
.d-s { fill: var(--doc-ink-mute); font-family: var(--doc-f-sans); font-size: 11px; }
.d-m { fill: var(--doc-ink-mute); font-family: var(--doc-f-mono); font-size: 10px; letter-spacing: .02em; }
.d-hd { fill: var(--doc-ink-mute); font-family: var(--doc-f-mono); font-size: 10.5px; letter-spacing: .1em; text-transform: uppercase; }
.d-l { stroke: currentColor; stroke-width: 1.1; fill: none; }
.d-l-a { stroke: var(--doc-accent); stroke-width: 1.4; fill: none; }
.d-ah { fill: currentColor; }
.d-ah-a { fill: var(--doc-accent); }

.flow { counter-reset: step; margin: 0 0 20px; max-width: var(--doc-measure); padding-left: 0; }
.flow > li { list-style: none; position: relative; padding-left: 36px; margin-bottom: 13px; }
.flow > li::before {
  counter-increment: step; content: counter(step);
  position: absolute; left: 0; top: 4px;
  font-family: var(--doc-f-mono); font-size: 11px;
  width: 22px; height: 22px; display: grid; place-items: center;
  border: 1px solid var(--doc-accent); color: var(--doc-accent); border-radius: 50%;
}

details.appx { border: 1px solid var(--doc-line); margin: 0 0 14px; }
details.appx > summary { padding: 12px 18px; cursor: pointer; font-weight: 640; background: var(--doc-surface); font-size: 15px; }
details.appx > summary:hover { color: var(--doc-accent); }
details.appx > div { padding: 14px 18px; border-top: 1px solid var(--doc-line-soft); }
details.appx p { font-size: 14px; }
details.appx code { font-size: 12.5px; }

footer { margin-top: 70px; padding-top: 24px; border-top: 1px solid var(--doc-line); font-size: 13.5px; color: var(--doc-ink-mute); max-width: var(--doc-measure); }

:focus-visible { outline: 2px solid var(--doc-accent); outline-offset: 2px; }
@media (prefers-reduced-motion: reduce) { * { transition: none !important; } }

@media (max-width: 900px) {
  .wrap { grid-template-columns: 1fr; gap: 0; padding: 0 20px 80px; }
  .rail { display: none; }
  main { padding-top: 8px; }
  .pat .row { grid-template-columns: 1fr; }
  .pat .lbl { padding: 12px 20px 0; line-height: 1.5; }
  .pat .bd { padding: 6px 20px 14px; }
}
